ALTER TABLE public.inbox_favorites DROP CONSTRAINT inbox_favorites_target_kind_check;
ALTER TABLE public.inbox_favorites ADD CONSTRAINT inbox_favorites_target_kind_check CHECK(target_kind IN ('lead','message','peer','peer_message','group'));
CREATE OR REPLACE FUNCTION public.inbox_favorite_target_access(_workspace uuid,_kind text,_target uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT ws_current_access(_workspace) AND CASE _kind WHEN 'group' THEN public.is_community_group_member(_target,auth.uid()) WHEN 'lead' THEN EXISTS (SELECT 1 FROM leads l WHERE l.id=_target AND l.workspace_owner_id=_workspace) WHEN 'message' THEN EXISTS (SELECT 1 FROM messages m LEFT JOIN leads l ON l.id=m.lead_id WHERE m.id=_target AND (l.workspace_owner_id=_workspace OR (m.lead_id IS NULL AND public.is_admin_or_above(auth.uid()) AND m.platform='whatsapp' AND m.direction='inbound' AND m.metadata->>'sender_phone' IS NOT NULL))) WHEN 'peer' THEN (public.is_community_chat_member(auth.uid()) AND _target<>auth.uid() AND public.is_community_chat_member(_target)) OR EXISTS (SELECT 1 FROM community_chat_messages c WHERE (c.sender_id=auth.uid() AND c.recipient_id=_target) OR (c.recipient_id=auth.uid() AND c.sender_id=_target)) WHEN 'peer_message' THEN EXISTS (SELECT 1 FROM community_chat_messages c WHERE c.id=_target AND (c.sender_id=auth.uid() OR c.recipient_id=auth.uid())) ELSE false END $$;
REVOKE ALL ON FUNCTION public.inbox_favorite_target_access(uuid,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.inbox_favorite_target_access(uuid,text,uuid) TO authenticated,service_role;
CREATE FUNCTION public.notify_chat_receipt_transition() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; BEGIN IF TG_OP='UPDATE' AND NEW.delivered_at IS NOT DISTINCT FROM OLD.delivered_at AND NEW.read_at IS NOT DISTINCT FROM OLD.read_at THEN RETURN NEW; END IF; IF NEW.delivered_at IS NULL AND NEW.read_at IS NULL THEN RETURN NEW; END IF; FOR uid IN SELECT NEW.user_id UNION SELECT sender_id FROM public.community_chat_messages WHERE NEW.kind='peer' AND id=NEW.message_id UNION SELECT sender_id FROM public.community_group_messages WHERE NEW.kind='group' AND id=NEW.message_id LOOP IF uid IS NOT NULL THEN PERFORM realtime.send('{}'::jsonb,'receipt_changed','inbox-events:'||uid::text,true); END IF; END LOOP; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.notify_chat_receipt_transition() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER chat_receipt_live_transition AFTER INSERT OR UPDATE ON public.chat_message_receipts FOR EACH ROW EXECUTE FUNCTION public.notify_chat_receipt_transition();